import path from 'node:path';
import fs from 'node:fs/promises';
import os from 'node:os';
import {after} from 'node:test';
import {createHash} from 'node:crypto';
import {PRIVATE_NATIVE_TOOL_REQUIRED_FILES,privateNativeToolsBinding,resolvePrivateNativeTools} from '../../../apps/metaengine-browser/src/private-native-tools-core.mjs';

// Inert generated bytes resolved by the actual package-data verifier. This is
// a test-only producer, never package release authority or executable evidence.
let generatedTools;
export function generatedInstalledTools(){
 return generatedTools??=Promise.resolve().then(async()=>{
  const root=await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(),'native-scope-tools-')));
  const resources=path.join(root,'resources'),toolsRoot=path.join(resources,'private-native-tools'),components=[];
  try{
   for(const [id,entrypoint]of [['git','ucrt64/bin/git.exe'],['codex','bin/codex.exe']]){
    const files=[];
    for(const name of [...PRIVATE_NATIVE_TOOL_REQUIRED_FILES[id]].sort()){
     const file=path.join(toolsRoot,id,name),bytes=Buffer.from('inert generated native scope: '+id+'/'+name);
     await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,bytes);
     files.push({path:name,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')});
    }
    components.push({id,version:id==='git'?'2.56.0.4':'0.166.0',repository:id==='git'?'git-for-windows/git':'openai/codex',tag:'generated',
     release_id:1,asset_id:2,archive_name:id+'.zip',archive_sha256:'a'.repeat(64),archive_bytes:1,entrypoint,files});
   }
   const bytes=Buffer.from(JSON.stringify({schema:'metaengine.private-native-tools.v1',platform:'win32',arch:'x64',components}));
   await fs.writeFile(path.join(toolsRoot,'manifest.json'),bytes);
   const privateTools=await resolvePrivateNativeTools({toolsRoot,binding:privateNativeToolsBinding(bytes)});
   return {root,resources,privateTools};
  }catch(error){await fs.rm(root,{recursive:true,force:true});throw error;}
 });
}
after(async()=>{if(generatedTools){const value=await generatedTools;await fs.rm(value.root,{recursive:true,force:true});}});

// Generated placement-only descriptor. These paths/digests are not installed
// payloads, ACL evidence, authenticated configuration or native qualification.
export function generatedInstalledOperator({resources,stateDirectory}){
 const bundle=path.join(resources,'private-native-tools');
 return {schema:'metaengine.native-coding.operator-paths.v1',
  cli_executable:path.join(bundle,'codex','bin','codex.exe'),
  git_executable:path.join(bundle,'git','ucrt64','bin','git.exe'),
  codex_home:path.join(stateDirectory,'codex-home'),journal_root:path.join(stateDirectory,'journal'),
  worker_temp_root:path.join(stateDirectory,'worker-temp'),result_index_root:path.join(stateDirectory,'result-index'),
  sandbox_receipts:{IMPLEMENTER:{path:path.join(stateDirectory,'canaries','implementer.json'),sha256:'a'.repeat(64)},
   CRITIC:{path:path.join(stateDirectory,'canaries','critic.json'),sha256:'b'.repeat(64)}}};
}

// Include the actual shared guard call when tests evaluate a smaller source
// closure. Fixtures replace protected reads, never the production path guard.
export function installedOperatorReaderSource(source){
 const start=source.indexOf('  async function readInstalledOperator('),end=source.indexOf('  async function prepareNativeScopes(',start);
 if(start<0||end<=start)throw Error('fixture_installed_operator_reader_missing');
 return source.slice(start,end);
}
